create extension if not exists pgcrypto;
do $$ begin create type user_status as enum('active','suspended','pending','deleted'); exception when duplicate_object then null; end $$;
do $$ begin create type order_status as enum('pending','paid','failed','cancelled','refunded'); exception when duplicate_object then null; end $$;
do $$ begin create type payment_status as enum('created','pending','verified','failed','refunded'); exception when duplicate_object then null; end $$;
do $$ begin create type content_status as enum('draft','pending_review','published','rejected','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type withdrawal_status as enum('pending','approved','rejected','paid','cancelled'); exception when duplicate_object then null; end $$;
do $$ begin create type ledger_status as enum('pending','available','withdrawn','reversed'); exception when duplicate_object then null; end $$;
do $$ begin create type registration_status as enum('registered','attended','cancelled','no_show'); exception when duplicate_object then null; end $$;
create table if not exists roles(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null);
create table if not exists permissions(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null);
create table if not exists role_permissions(role_id uuid references roles(id) on delete cascade,permission_id uuid references permissions(id) on delete cascade,primary key(role_id,permission_id));
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,full_name text not null,password_hash text not null,status user_status not null default 'active',theme_preference text not null default 'system',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists user_roles(user_id uuid references users(id) on delete cascade,role_id uuid references roles(id) on delete restrict,primary key(user_id,role_id));
create table if not exists partners(id uuid primary key default gen_random_uuid(),user_id uuid unique references users(id) on delete cascade,referral_code text unique not null,status text not null default 'active',minimum_withdrawal_inr numeric(12,2) not null default 100,created_at timestamptz not null default now());
create table if not exists instructors(id uuid primary key default gen_random_uuid(),user_id uuid unique references users(id) on delete cascade,bio text,status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,active boolean not null default true);
create table if not exists packages(id uuid primary key default gen_random_uuid(),slug text unique not null,name text unique not null,subtitle text not null,description text,price_inr numeric(12,2) not null check(price_inr>=0),thumbnail_url text,access_duration_days integer,active boolean not null default true,featured boolean not null default false,discount_percent numeric(5,2) not null default 0,display_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),instructor_id uuid references instructors(id) on delete set null,category_id uuid references categories(id) on delete set null,title text not null,slug text unique not null,description text,price_inr numeric(12,2) not null default 0,thumbnail_url text,status content_status not null default 'draft',published_at timestamptz,created_at timestamptz not null default now());
create table if not exists package_courses(package_id uuid references packages(id) on delete cascade,course_id uuid references courses(id) on delete cascade,primary key(package_id,course_id));
create table if not exists lessons(id uuid primary key default gen_random_uuid(),course_id uuid references courses(id) on delete cascade,title text not null,description text,content_url text,position int default 0,published boolean default false,created_at timestamptz default now());
create table if not exists masterclasses(id uuid primary key default gen_random_uuid(),instructor_id uuid references instructors(id) on delete set null,title text not null,description text,thumbnail_url text,price_inr numeric(12,2) not null default 0,mode text not null default 'live',schedule_at timestamptz,seats int,status content_status not null default 'draft',recording_url text,created_at timestamptz default now());
create table if not exists workshops(id uuid primary key default gen_random_uuid(),instructor_id uuid references instructors(id) on delete set null,title text not null,description text,price_inr numeric(12,2) not null default 0,schedule_at timestamptz,seats int,status content_status not null default 'draft',recording_url text,created_at timestamptz default now());
create table if not exists coupons(id uuid primary key default gen_random_uuid(),code text unique not null,discount_type text not null check(discount_type in('fixed','percent')),value numeric(12,2) not null,active boolean default true,valid_from timestamptz,valid_until timestamptz);
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete restrict,order_type text not null,package_id uuid references packages(id) on delete restrict,course_id uuid references courses(id) on delete restrict,masterclass_id uuid references masterclasses(id) on delete restrict,workshop_id uuid references workshops(id) on delete restrict,subtotal_inr numeric(12,2) not null,discount_inr numeric(12,2) not null default 0,total_inr numeric(12,2) not null,coupon_code text,referral_code text,status order_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid unique references orders(id) on delete restrict,provider text not null default 'manual',provider_payment_id text,amount_inr numeric(12,2) not null,status payment_status not null default 'created',verified_at timestamptz,verified_by uuid references users(id),created_at timestamptz default now());
create table if not exists enrollments(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,package_id uuid references packages(id) on delete restrict,course_id uuid references courses(id) on delete restrict,order_id uuid references orders(id) on delete restrict,access_started_at timestamptz default now(),access_expires_at timestamptz,progress_percent numeric(5,2) default 0,created_at timestamptz default now(),unique(user_id,package_id,order_id),unique(user_id,course_id,order_id));
create table if not exists referrals(id uuid primary key default gen_random_uuid(),partner_id uuid references partners(id) on delete cascade,referred_user_id uuid references users(id) on delete cascade,source text,status text not null default 'pending',converted_order_id uuid references orders(id),first_attributed_at timestamptz default now(),converted_at timestamptz,unique(partner_id,referred_user_id));
create table if not exists commission_rules(id uuid primary key default gen_random_uuid(),package_id uuid references packages(id) on delete cascade,commission_type text not null check(commission_type in('fixed','percent')),value numeric(12,2) not null,active boolean default true,effective_from timestamptz default now(),effective_to timestamptz);
create table if not exists commissions(id uuid primary key default gen_random_uuid(),partner_id uuid references partners(id) on delete restrict,order_id uuid references orders(id) on delete restrict,rule_id uuid references commission_rules(id),amount_inr numeric(12,2) not null,status ledger_status default 'pending',created_at timestamptz default now(),unique(partner_id,order_id));
create table if not exists earnings_ledger(id uuid primary key default gen_random_uuid(),partner_id uuid references partners(id) on delete restrict,commission_id uuid references commissions(id),amount_inr numeric(12,2) not null,status ledger_status not null default 'pending',description text,created_at timestamptz default now());
create table if not exists withdrawals(id uuid primary key default gen_random_uuid(),partner_id uuid references partners(id) on delete restrict,amount_inr numeric(12,2) not null check(amount_inr>=100),status withdrawal_status not null default 'pending',reviewed_by uuid references users(id),reviewed_at timestamptz,rejection_reason text,paid_at timestamptz,created_at timestamptz default now());
create table if not exists qr_codes(id uuid primary key default gen_random_uuid(),partner_id uuid references partners(id) on delete cascade,code text unique not null,destination_path text not null,active boolean default true,created_at timestamptz default now());
create table if not exists registrations(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,masterclass_id uuid references masterclasses(id) on delete cascade,workshop_id uuid references workshops(id) on delete cascade,order_id uuid references orders(id),status registration_status default 'registered',attendance_at timestamptz,created_at timestamptz default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,course_id uuid references courses(id) on delete cascade,masterclass_id uuid references masterclasses(id) on delete cascade,workshop_id uuid references workshops(id) on delete cascade,rating int check(rating between 1 and 5),body text,status text default 'pending',created_at timestamptz default now());
create table if not exists certificates(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,course_id uuid references courses(id),certificate_code text unique not null,issued_at timestamptz default now(),metadata jsonb default '{}'::jsonb);
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,title text not null,body text not null,read_at timestamptz,created_at timestamptz default now());
create table if not exists support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,subject text not null,body text not null,status text default 'open',assigned_to uuid references users(id),created_at timestamptz default now());
create table if not exists levels(level_number int primary key check(level_number between 1 and 9),points_required int not null);
create table if not exists point_ledger(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,source_type text not null,source_id uuid not null,points_delta int not null,status text default 'valid',description text,created_at timestamptz default now(),unique(source_type,source_id,user_id));
create table if not exists skill_mastery(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,skill_name text not null,status text default 'pending',verified_by uuid references users(id),created_at timestamptz default now());
create table if not exists user_levels(user_id uuid primary key references users(id) on delete cascade,current_level int references levels(level_number) default 1,points int default 0,valid_referrals int default 0,verified_mastery_count int default 0,updated_at timestamptz default now());
create table if not exists rewards(id uuid primary key default gen_random_uuid(),level_number int references levels(level_number),name text not null,description text,image_url text,active boolean default true);
create table if not exists reward_claims(id uuid primary key default gen_random_uuid(),reward_id uuid references rewards(id),user_id uuid references users(id),eligibility_snapshot jsonb default '{}'::jsonb,status text default 'pending',approved_by uuid references users(id),approved_at timestamptz,delivery_status text,created_at timestamptz default now(),unique(reward_id,user_id));
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid references users(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb default '{}'::jsonb,ip_address inet,user_agent text,created_at timestamptz default now());
create index if not exists idx_users_email on users(email);create index if not exists idx_orders_user on orders(user_id);create index if not exists idx_orders_status on orders(status);create index if not exists idx_referrals_partner on referrals(partner_id);create index if not exists idx_ledger_partner on earnings_ledger(partner_id,status);create index if not exists idx_withdrawals_status on withdrawals(status);create index if not exists idx_points_user on point_ledger(user_id);create index if not exists idx_audit_created on audit_logs(created_at desc);
